const es = new EventSource('/__dfw/events');
es.addEventListener('design', async (e) => {
  const { files = [] } = JSON.parse(e.data);
  if (files.some((f) => /(^|\/)design\.json$/.test(f))) return loadAll({ keepCam: true });
  if (files.some((f) => f.startsWith('tokens/'))) S.tokens = await api('/__dfw/api/tokens').catch(() => S.tokens);
  if (files.some((f) => f.startsWith('system/'))) S.components = new Map((await api('/__dfw/api/components').catch(() => [])).map((c) => [c.name, c]));
  const screenOnly = files.every((f) => f.endsWith('.html') && !f.startsWith('system/') && !f.startsWith('components/'));
  for (const f of S.frames.values()) {
    if (!f.iframe) continue;
    if (!screenOnly || (f.file && files.includes(f.file))) softReload(f, files);
  }
  if (P.open && (!screenOnly || (P.file && files.includes(P.file)))) loadPresent();
});
// The agent is about to edit a design file: point at the element in the frames that show it.
es.addEventListener('presence', (e) => {
  const { file = '', dfwId = null } = JSON.parse(e.data);
  const component = /^system\/components\/([\w-]+)\.html$/.exec(file)?.[1] || null;
  for (const f of S.frames.values()) {
    if (!f.iframe || !f.loaded) continue;
    if (f.system) {
      if (component) post(f, { type: 'dfw:presence', dfwId: `system.component.${component}` });
      else if (file.startsWith('tokens/')) post(f, { type: 'dfw:presence', dfwId: 'system.colors' });
    } else if (f.file === file) post(f, { type: 'dfw:presence', dfwId, fallback: true });
    else if (component) post(f, { type: 'dfw:presence', component });
  }
});
es.addEventListener('comments', () => loadComments());

window.__dfwStudio = S; // for debugging and e2e tests
setMode('select');
loadAll().catch((e) => toast(e.message));

/* dfw Studio chrome: quiet, dense, Figma-like. Tool UI only; designs carry the colour. */
:root {
  --canvas: #e8e8e6;
  --panel: #ffffff;
  --panel-2: #f5f5f5;
  --hover: #f0f0f0;
  --ink: #1e1e1e;
  --ink-2: #4d4d4d;
  --ink-3: #8c8c8c;
  --line: #e6e6e6;
  --line-strong: #d0d0d0;
  --accent: #0d99ff;
  --accent-soft: #e5f4ff;
  --component: #9747ff;
  --component-soft: #f1e8ff;
  --warn: #c2410c;
  --warn-soft: #fff1e6;
  --open: #c2410c;
  --fixed: #a16207;
  --resolved: #15803d;
  --dismissed: #78716c;
  --frame-title: #6b6b6b;
  --sec-bg: #f5f5f3;
  --sec-ink: #1e1e1e;
  --sec-ink-2: #5c5c5c;
  --note-bg: #ffffff;
  --note-line: #dcdcdc;
  --font: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root {
    --canvas: #1e1e1e;
    --panel: #2c2c2c;
    --panel-2: #383838;
    --hover: #3a3a3a;
    --ink: #f0f0f0;
    --ink-2: #c8c8c8;
    --ink-3: #8f8f8f;
    --line: #3d3d3d;
    --line-strong: #4d4d4d;
    --accent: #0c8ce9;
    --accent-soft: #0c3a5c;
    --component: #a879ff;
    --component-soft: #3b2a5c;
    --warn: #fb923c;
    --warn-soft: #4a2a14;
    --open: #fb923c;
    --fixed: #facc15;
    --resolved: #4ade80;
    --dismissed: #a8a29e;
    --frame-title: #a0a0a0;
    --sec-bg: #262626;
    --sec-ink: #ededed;
    --sec-ink-2: #a8a8a8;
    --note-bg: #2f2f2f;
    --note-line: #444;
    color-scheme: dark;
  }
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body { height: 100%; }
body { margin: 0; background: var(--canvas); color: var(--ink); font: 11px/1.45 var(--font); overflow: hidden; -webkit-font-smoothing: antialiased; }
button, select, textarea, input { font: inherit; color: inherit; }
button { cursor: pointer; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
code, kbd { font-family: var(--mono); font-size: 10px; }
kbd { border: 1px solid var(--line-strong); border-radius: 3px; padding: 0 3px; background: var(--panel-2); }
.muted { color: var(--ink-3); }
.small { font-size: 11px; }

/* Top bar */
.topbar { height: 44px; display: grid; grid-template-columns: 240px 1fr auto; align-items: center; background: var(--panel); border-bottom: 1px solid var(--line); position: relative; z-index: 5; }
.brand { display: flex; align-items: center; gap: 8px; padding: 0 12px; min-width: 0; white-space: nowrap; overflow: hidden; }
.brand-mark { width: 14px; height: 14px; border-radius: 3px; background: conic-gradient(from 45deg, #0d99ff, #9747ff, #ff7262, #0acf83, #0d99ff); flex: none; }
.brand strong { font-size: 12px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; }
#meta { overflow: hidden; text-overflow: ellipsis; }
.tools { display: flex; align-items: center; gap: 6px; padding: 0 8px; min-width: 0; overflow: hidden; }
.seg { display: flex; gap: 2px; padding: 2px; border-radius: 7px; background: var(--panel-2); }
.seg button, .icon-btn { width: 30px; height: 28px; display: grid; place-items: center; border: 0; border-radius: 5px; background: transparent; color: var(--ink-2); }
.seg button svg { width: 15px; height: 15px; }
.seg button:hover, .icon-btn:hover { background: var(--hover); }
.seg button[aria-checked="true"] { background: var(--accent); color: #fff; box-shadow: 0 1px 2px rgb(0 0 0 / 0.15); }
.sep { width: 1px; height: 20px; background: var(--line); margin: 0 4px; }
.chips { display: flex; gap: 2px; }
.chip, .chips button { height: 26px; padding: 0 9px; border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--ink-2); white-space: nowrap; }
.chip:hover, .chips button:hover { background: var(--hover); }
.chip[aria-pressed="true"], .chips button[aria-pressed="true"] { background: var(--accent-soft); color: var(--accent); }
.ms { position: relative; } /* list is fixed (no top/left): sits under the summary and escapes .tools overflow */
.ms > summary { display: flex; align-items: center; gap: 4px; cursor: pointer; list-style: none; line-height: 26px; }
.ms > summary::-webkit-details-marker { display: none; }
.ms > summary::after { content: "\25BE"; font-size: 10px; color: var(--ink-3); }
.ms[open] > summary { background: var(--hover); }
.ms-list { position: fixed; margin-top: 4px; min-width: 180px; max-height: 60vh; overflow: auto; padding: 4px; background: var(--panel); border: 1px solid var(--line); border-radius: 8px; box-shadow: 0 6px 20px rgb(0 0 0 / 0.15); z-index: 30; }
.ms-list label { display: flex; align-items: center; gap: 8px; padding: 4px 8px; border-radius: 5px; white-space: nowrap; cursor: pointer; }
.ms-list label:hover { background: var(--hover); }
.shoot-menu > summary::after { content: none; }
.shoot-menu > summary { display: grid; line-height: normal; }
.icon-btn svg { width: 15px; height: 15px; }
.shoot-list { min-width: 260px; padding: 0; }
.shoot-items { max-height: calc(60vh - 48px); overflow: auto; padding: 4px; }
.shoot-items .shoot-page { font-weight: 600; margin-top: 4px; }
.shoot-items .shoot-screen { padding-left: 26px; }
.shoot-items .shoot-n { margin-left: auto; padding-left: 12px; color: var(--ink-3); font-size: 11px; }
.shoot-foot { position: sticky; bottom: 0; display: flex; align-items: center; gap: 8px; padding: 8px; border-top: 1px solid var(--line); background: var(--panel); color: var(--ink-3); font-size: 11px; }
.shoot-go { margin-left: auto; height: 26px; padding: 0 12px; border: 0; border-radius: 6px; background: var(--accent); color: #fff; font-weight: 600; cursor: pointer; }
.shoot-go:disabled { opacity: .5; cursor: default; }
.ms-list .ms-all { border-bottom: 1px solid var(--line); border-radius: 5px 5px 0 0; margin-bottom: 2px; font-weight: 600; }
.select { display: flex; align-items: center; gap: 4px; color: var(--ink-3); }
.select select { height: 24px; border: 1px solid var(--line); border-radius: 4px; background: var(--panel); padding: 0 4px; }
.right { display: flex; align-items: center; gap: 4px; padding: 0 8px; }
.zoom { display: flex; align-items: center; }
.zoom button { height: 26px; min-width: 24px; border: 0; background: transparent; border-radius: 4px; color: var(--ink-2); }
.zoom button:hover { background: var(--hover); }
#zoom-label { min-width: 46px; font-variant-numeric: tabular-nums; }

/* Layout */
.layout { display: grid; grid-template-columns: 240px 1fr 296px; height: calc(100% - 44px); }
.left, .right-panel { background: var(--panel); min-height: 0; display: flex; flex-direction: column; position: relative; z-index: 4; }
.left { border-right: 1px solid var(--line); }
.right-panel { border-left: 1px solid var(--line); }
.pane { display: flex; flex-direction: column; min-height: 0; }
.pages-pane { flex: none; max-height: 40%; border-bottom: 1px solid var(--line); }
.layers-pane { flex: 1; }
.pane-title { margin: 0; padding: 12px 14px 6px; font-size: 11px; font-weight: 600; letter-spacing: 0.01em; display: flex; gap: 6px; align-items: baseline; }
.pane-title .muted { font-weight: 400; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.page-list { list-style: none; margin: 0; padding: 0 4px 8px; overflow: auto; }
.page-list button { width: 100%; display: flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border: 0; border-radius: 6px; background: transparent; text-align: left; }
.page-list button:hover { background: var(--hover); }
.page-list button[aria-current="page"] { background: var(--accent-soft); font-weight: 600; }
.page-list button.all { color: var(--ink-2); }
.page-list button.focus { box-shadow: inset 2px 0 0 var(--accent); }
.present-btn { margin-left: 2px; color: var(--ink-2); }

/* Page sections on the canvas: typeset like a design file (world units, scale with zoom). */
svg.flow { position: absolute; left: 0; top: 0; overflow: visible; pointer-events: none; z-index: 1; }
svg.flow path { fill: none; stroke: var(--accent); stroke-width: 4; opacity: 0.85; }
svg.flow marker path { fill: var(--accent); stroke: none; }
svg.flow text { fill: var(--accent); font: 600 22px var(--font); text-anchor: middle; paint-order: stroke; stroke: var(--canvas); stroke-width: 8px; }
.psec { position: absolute; background: var(--sec-bg); border-radius: 2px; }
.psec-label { position: absolute; left: 0; bottom: 100%; padding-bottom: calc(6px * var(--iz)); font-size: calc(12px * var(--iz)); font-weight: 600; color: var(--frame-title); white-space: nowrap; }
.psec-head { position: absolute; max-width: 1600px; color: var(--sec-ink); }
.psec-head h1 { margin: 0; font: 600 56px/1.08 var(--font); letter-spacing: -0.02em; white-space: nowrap; }
.psec-head p { margin: 14px 0 0; font-size: 22px; line-height: 1.5; color: var(--sec-ink-2); width: max-content; max-width: 1200px; }
.prow-gutter { position: absolute; color: var(--sec-ink); }
.prow-gutter > h2 { margin: 0; font: 600 32px/1.15 var(--font); letter-spacing: -0.01em; }
.prow-gutter > p { margin: 8px 0 0; font-size: 16px; color: var(--sec-ink-2); }
.notes { background: var(--note-bg); border: 1px solid var(--note-line); border-radius: 8px; padding: 28px; }
.notes h3 { margin: 0; font: 600 30px/1.15 var(--font); letter-spacing: -0.01em; }
.notes .nsub { margin: 6px 0 0; font-size: 15px; color: var(--sec-ink-2); }
.notes .ng { margin-top: 22px; }
.notes h4 { margin: 0 0 8px; font-size: 13px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--sec-ink-2); }
.notes ul { margin: 0; padding: 0; list-style: none; }
.notes li { position: relative; padding-left: 14px; font-size: 17px; line-height: 1.5; margin: 3px 0; }
.notes li::before { content: "·"; position: absolute; left: 2px; font-weight: 700; }

/* Presenter: nav (fixed width) | title (shrinks, ellipsis) | controls. Long titles never move the arrows. */
.present { position: fixed; inset: 0; z-index: 25; background: #0f0f10; display: flex; flex-direction: column; color: #ececec; }
.p-bar { height: 48px; flex: none; display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; align-items: center; gap: 12px; padding: 0 10px; background: #18181a; border-bottom: 1px solid #262629; font-size: 12px; }
.p-nav { display: flex; align-items: center; gap: 2px; padding: 2px; border-radius: 8px; background: #222225; }
.p-nav button { width: 30px; height: 28px; display: grid; place-items: center; border: 0; border-radius: 6px; background: transparent; color: #ddd; }
.p-nav button svg { width: 15px; height: 15px; }
.p-nav button:hover { background: #303034; color: #fff; }
.p-count { min-width: 64px; text-align: center; color: #9b9ba1; font-variant-numeric: tabular-nums; white-space: nowrap; }
.p-title { min-width: 0; font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.p-group { display: flex; align-items: center; gap: 6px; }
.p-btn { height: 30px; min-width: 30px; padding: 0 10px; border: 1px solid #2e2e32; border-radius: 6px; background: #222225; color: #e6e6e6; text-decoration: none; display: inline-flex; align-items: center; justify-content: center; font-size: 12px; white-space: nowrap; }
.p-btn:hover { background: #2c2c30; color: #fff; }
.p-btn[aria-pressed="true"]#p-comment, .p-btn[aria-pressed="true"]#p-pins { background: #0d99ff; border-color: #0d99ff; color: #fff; }
.p-sel { display: flex; align-items: center; gap: 6px; color: #8e8e94; white-space: nowrap; }
.p-sel select { height: 30px; max-width: 200px; background: #222225; color: #eee; border: 1px solid #2e2e32; border-radius: 6px; padding: 0 6px; }
.p-sel select:disabled { opacity: 0.45; }
@media (max-width: 1180px) { .p-sel > span { display: none; } }
@media (max-width: 960px) { #p-fit, #p-full { display: none; } }
.p-stage { flex: 1; min-height: 0; overflow: auto; padding: 16px 0; }
.p-wrap { margin: 0 auto; position: relative; overflow: hidden; background: #fff; border-radius: 4px; box-shadow: 0 0 0 1px rgb(255 255 255 / 0.06), 0 20px 60px rgb(0 0 0 / 0.55); }
.p-wrap iframe { border: 0; display: block; transform-origin: 0 0; background: #fff; }
.page-list .n { margin-left: auto; color: var(--ink-3); font-variant-numeric: tabular-nums; font-weight: 400; }
.page-list .c { background: var(--open); color: #fff; border-radius: 8px; padding: 0 5px; font-size: 10px; font-weight: 600; }
.layers { overflow: auto; flex: 1; padding: 0 4px 12px; }
.layers .row { display: flex; align-items: center; gap: 4px; height: 24px; padding-right: 6px; border-radius: 4px; cursor: default; white-space: nowrap; overflow: hidden; }
.layers .row:hover { background: var(--hover); }
.layers .row[aria-selected="true"] { background: var(--accent-soft); }
.layers .row.comp { color: var(--component); }
.layers .row.comp[aria-selected="true"] { background: var(--component-soft); }
.layers .row.hidden-layer { opacity: 0.45; }
.layers .tw { width: 14px; flex: none; text-align: center; color: var(--ink-2); border: 0; background: none; padding: 0; font-size: 10px; line-height: 1; }
.layers .ic { width: 12px; flex: none; color: var(--ink-3); font-size: 10px; text-align: center; }
.layers .comp .ic { color: var(--component); }
.layers .nm { overflow: hidden; text-overflow: ellipsis; }
.layers .sub { color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; }
.hint { padding: 8px 12px; margin: 0; }

/* Canvas */
.viewport { position: relative; overflow: hidden; background: var(--canvas); outline: none; cursor: default; touch-action: none; }
body[data-mode="hand"] .viewport, body.space .viewport { cursor: grab; }
body.panning .viewport { cursor: grabbing; }
body[data-mode="hand"] .world iframe, body.space .world iframe, body.panning .world iframe { pointer-events: none; }
.world { position: absolute; left: 0; top: 0; transform-origin: 0 0; --iz: 1; }
.world.moving { will-change: transform; }
.frame { position: absolute; background: #fff; box-shadow: 0 0 0 calc(1px * var(--iz)) rgb(0 0 0 / 0.07), 0 calc(4px * var(--iz)) calc(18px * var(--iz)) rgb(0 0 0 / 0.07); }
.frame iframe { border: 0; display: block; width: 100%; height: 100%; background: #fff; }
.frame.selected { outline: calc(2px * var(--iz)) solid var(--accent); }
.frame.flash { animation: flash 1.2s ease-out; }
@keyframes flash { 0% { outline: calc(4px * var(--iz)) solid var(--accent); } 100% { outline: 0 solid transparent; } }
.frame-title { position: absolute; left: 0; bottom: 100%; padding-bottom: calc(4px * var(--iz)); font-size: calc(11px * var(--iz)); line-height: 1.3; color: var(--frame-title); white-space: nowrap; max-width: 100%; overflow: hidden; text-overflow: ellipsis; cursor: default; user-select: none; }
.frame-title:hover, .frame.selected .frame-title { color: var(--accent); }
.frame-title .st { color: var(--warn); }
.frame-title a { color: inherit; margin-left: 0.5em; opacity: 0; text-decoration: none; }
.frame-title:hover a { opacity: 1; }
.frame .placeholder { position: absolute; inset: 0; display: grid; place-items: center; color: #bbb; font-size: calc(12px * var(--iz)); }
.row-title { position: absolute; font-size: calc(14px * var(--iz)); font-weight: 600; color: var(--ink); white-space: nowrap; transform: translateY(-100%); padding-bottom: calc(22px * var(--iz)); user-select: none; }
.row-title .d { font-weight: 400; color: var(--ink-3); margin-left: 0.6em; font-size: 0.85em; }
.world.tiny .row-title, .world.tiny .frame-title { display: none; }

.hud { position: fixed; inset: 0; pointer-events: none; z-index: 26; }
.box { position: absolute; left: 0; top: 0; }
.box.hover { border: 1px solid var(--accent); }
.box.hover.comp { border-color: var(--component); }
.box.sel { border: 2px solid var(--accent); }
.box.sel.comp { border-color: var(--component); }
.box .tag, .box .dims { position: absolute; left: -2px; font: 600 10px/16px var(--font); padding: 0 5px; border-radius: 2px; color: #fff; background: var(--accent); white-space: nowrap; }
.box .tag { bottom: 100%; margin-bottom: 2px; }
.box .dims { top: 100%; margin-top: 3px; left: 50%; transform: translateX(-50%); font-weight: 500; }
.box.comp .tag, .box.comp .dims { background: var(--component); }
/* Agent presence: where Claude is editing (dashed) or what it just changed (solid, fades). The cursor glides between them. */
.box.agent { border: 2px dashed var(--agent, #c2410c); border-radius: 3px; transition: transform .25s ease, width .25s ease, height .25s ease; }
.box.agent .tag { background: var(--agent, #c2410c); left: -2px; font-size: 11px; line-height: 18px; }
.box.agent.changed { border-style: solid; background: color-mix(in srgb, var(--agent, #c2410c) 10%, transparent); animation: agent-fade 2.6s ease-out forwards; }
@keyframes agent-fade { 0%, 60% { opacity: 1; } 100% { opacity: 0; } }
.agent-cursor { position: absolute; left: 0; top: 0; overflow: visible; transition: transform .35s cubic-bezier(.2, .8, .2, 1); filter: drop-shadow(0 1px 2px rgb(0 0 0 / .35)); }
.agent-cursor path { fill: var(--agent, #c2410c); stroke: #fff; stroke-width: 1.5; stroke-linejoin: round; }
@media (prefers-reduced-motion: reduce) { .box.agent, .agent-cursor { transition: none; } .box.agent.changed { animation-duration: .01s; animation-delay: 2.5s; } }

#pins button { position: absolute; pointer-events: auto; min-width: 22px; height: 22px; padding: 0 6px; border-radius: 11px 11px 11px 3px; border: 2px solid #fff; color: #fff; font: 700 10.5px/18px var(--font); box-shadow: 0 2px 6px rgb(0 0 0 / 0.28); transform: translate(-2px, -100%); transition: transform 0.12s ease; }
#pins button:hover { transform: translate(-2px, -100%) scale(1.12); }
#pins button.on { box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 45%, transparent), 0 2px 6px rgb(0 0 0 / 0.28); }
#pins button[data-s="resolved"] { opacity: 0.7; }

/* Pin popover: read a comment where it was made */
.pin-pop { position: fixed; z-index: 29; width: 300px; max-height: min(420px, calc(100vh - 64px)); overflow: auto; background: var(--panel); color: var(--ink); border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px; box-shadow: 0 12px 36px rgb(0 0 0 / 0.22); font-size: 12px; }
.pop-head { display: flex; align-items: center; gap: 8px; }
.pop-head .num { font-weight: 700; }
.pop-head .status { margin-left: 0; }
.pop-x { margin-left: auto; width: 24px; height: 24px; border: 0; border-radius: 5px; background: none; color: var(--ink-3); }
.pop-x:hover { background: var(--hover); color: var(--ink); }
.pop-text { margin: 8px 0 0; font-size: 13px; line-height: 1.5; white-space: pre-wrap; overflow-wrap: anywhere; }
.pop-where { margin: 6px 0 0; color: var(--ink-3); font-size: 11px; overflow-wrap: anywhere; }
.pin-pop .thread { margin-top: 10px; }
.pin-pop .comment-actions { margin-top: 10px; }
.empty { position: absolute; top: 40%; left: 50%; transform: translate(-50%, -50%); color: var(--ink-3); font-size: 12px; text-align: center; max-width: 360px; }

/* Right panel */
.ptabs { display: flex; gap: 2px; padding: 8px 10px; border-bottom: 1px solid var(--line); }
.ptabs button { height: 28px; padding: 0 10px; border: 0; border-radius: 6px; background: none; color: var(--ink-3); font-weight: 600; }
.ptabs button[aria-selected="true"] { color: var(--ink); background: var(--panel-2); }
.count { display: inline-block; min-width: 16px; padding: 0 4px; border-radius: 8px; background: var(--panel-2); color: var(--ink-2); font-size: 10px; text-align: center; }
.tabpane { flex: 1; min-height: 0; overflow: auto; display: flex; flex-direction: column; }
#inspector { padding-bottom: 16px; }
.isec { border-bottom: 1px solid var(--line); padding: 8px 12px 10px; }
.isec h3 { margin: 0 0 6px; font-size: 11px; font-weight: 600; display: flex; align-items: center; gap: 6px; }
.isec h3 .sp { margin-left: auto; }
.ihead { display: flex; align-items: center; gap: 6px; font-weight: 600; font-size: 12px; word-break: break-all; }
.ihead.comp { color: var(--component); }
.kv { display: grid; grid-template-columns: 76px 1fr; gap: 4px 8px; align-items: center; }
.kv dt { color: var(--ink-3); }
.kv dd { margin: 0; min-width: 0; overflow-wrap: anywhere; }
.kv select, .kv input { width: 100%; height: 24px; border: 1px solid var(--line); border-radius: 4px; background: var(--panel); padding: 0 4px; }
.kv select:hover, .kv input:hover { border-color: var(--line-strong); }
.tok { position: relative; display: grid; grid-template-columns: 78px minmax(0, 1fr); gap: 2px 6px; align-items: start; padding: 3px 0; }
.tok .ask { position: absolute; right: 0; top: 3px; visibility: hidden; height: 20px; padding: 0 6px; border: 1px solid var(--line-strong); border-radius: 4px; background: var(--panel); font-size: 10px; color: var(--ink-2); white-space: nowrap; }
.tok:hover .ask, .tok .ask:focus-visible { visibility: visible; }
.tok .ask:hover { background: var(--hover); }
.tok .p { color: var(--ink-3); padding-top: 3px; }
.tok .v { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.tok .name { font-family: var(--mono); font-size: 10.5px; display: flex; align-items: center; gap: 5px; padding-top: 3px; }
.tok .raw { color: var(--ink-3); font-family: var(--mono); font-size: 10px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tok .none { color: var(--warn); font-family: var(--font); font-size: 11px; white-space: nowrap; }
.tok .sw { width: 12px; height: 12px; border-radius: 2px; flex: none; box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.15); }
.tok select { width: 100%; height: 22px; border: 1px solid var(--line); border-radius: 4px; background: var(--panel); font-family: var(--mono); font-size: 10.5px; max-width: 100%; }
.btn { height: 24px; padding: 0 8px; border: 1px solid var(--line-strong); border-radius: 4px; background: var(--panel); white-space: nowrap; }
.btn:hover { background: var(--hover); }
.btn.comp { color: var(--component); border-color: var(--component); }
.btn.small { height: 20px; padding: 0 6px; font-size: 10px; }
.btn-row { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
.note { color: var(--ink-3); margin: 6px 0 0; }

/* Comments */
.panel-head { display: flex; align-items: center; justify-content: space-between; gap: 6px; padding: 6px 8px; border-bottom: 1px solid var(--line); }
.tabs { display: flex; gap: 1px; }
.tabs button { height: 22px; padding: 0 6px; border: 0; border-radius: 4px; background: none; color: var(--ink-3); }
.tabs button[aria-selected="true"] { background: var(--panel-2); color: var(--ink); font-weight: 600; }
.link { border: 0; background: none; color: var(--accent); padding: 0; }
.comment-list { list-style: none; margin: 0; padding: 8px; flex: 1; display: flex; flex-direction: column; gap: 6px; }
.comment { position: relative; padding: 10px 12px 10px 14px; border: 1px solid var(--line); border-radius: 8px; background: var(--panel); cursor: pointer; overflow: hidden; }
.comment::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--dismissed); }
.comment:has(.status[data-s="open"])::before, .comment:has(.status[data-s="reopened"])::before { background: var(--open); }
.comment:has(.status[data-s="acknowledged"])::before { background: var(--accent); }
.comment:has(.status[data-s="fixed"])::before { background: var(--fixed); }
.comment:has(.status[data-s="resolved"])::before { background: var(--resolved); }
.comment:hover { border-color: var(--line-strong); }
.comment.selected { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.comment-top { display: flex; gap: 6px; align-items: center; color: var(--ink-3); }
.comment-top .num { font-weight: 700; color: var(--ink); }
.status { margin-left: auto; font-weight: 600; font-size: 10px; padding: 1px 7px; border-radius: 9px; white-space: nowrap; background: var(--panel-2); }
.status[data-s="open"], .status[data-s="reopened"] { color: var(--open); background: color-mix(in srgb, var(--open) 12%, transparent); }
.status[data-s="acknowledged"] { color: var(--accent); background: var(--accent-soft); }
.status[data-s="acknowledged"]::before { content: ""; display: inline-block; width: 6px; height: 6px; margin-right: 5px; border-radius: 50%; background: currentColor; animation: pulse 1.2s ease-in-out infinite; vertical-align: 1px; }
@keyframes pulse { 50% { opacity: 0.25; } }
.status[data-s="fixed"] { color: var(--fixed); background: color-mix(in srgb, var(--fixed) 14%, transparent); }
.status[data-s="resolved"] { color: var(--resolved); background: color-mix(in srgb, var(--resolved) 12%, transparent); }
.status[data-s="dismissed"] { color: var(--dismissed); }
.comment-target { font-family: var(--mono); font-size: 10px; color: var(--ink-3); margin-top: 2px; overflow-wrap: anywhere; }
.comment-text { margin: 6px 0 0; font-size: 12.5px; line-height: 1.5; white-space: pre-wrap; overflow-wrap: anywhere; }
.thread { list-style: none; margin: 6px 0 0; padding: 0 0 0 8px; border-left: 2px solid var(--line); }
.thread .by { display: block; color: var(--ink-3); font-size: 10px; }
.comment-actions { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.comment-actions button { height: 26px; padding: 0 9px; border: 1px solid var(--line-strong); border-radius: 6px; background: var(--panel); }
.comment-actions button:hover { background: var(--hover); }
.comment-actions button.ok { border-color: var(--resolved); background: var(--resolved); color: #fff; font-weight: 600; }
.comment-actions button.ok:hover { filter: brightness(1.08); background: var(--resolved); }
.comment-actions textarea { width: 100%; border: 1px solid var(--line-strong); border-radius: 4px; padding: 4px; background: var(--panel); }

/* Composer, sheet, toast */
.composer { position: fixed; z-index: 28; width: 320px; background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 12px; box-shadow: 0 8px 28px rgb(0 0 0 / 0.18); }
.composer-target { margin: 0 0 6px; font-family: var(--mono); font-size: 10px; color: var(--ink-3); overflow-wrap: anywhere; }
.composer textarea { width: 100%; border: 1px solid var(--line-strong); border-radius: 4px; padding: 6px; resize: vertical; background: var(--panel); font-size: 12px; }
.composer-actions { display: flex; gap: 6px; align-items: center; margin-top: 8px; }
.composer-actions .muted { margin-right: auto; }
.ghost { height: 26px; padding: 0 10px; border: 1px solid var(--line-strong); border-radius: 4px; background: var(--panel); }
.primary { height: 26px; padding: 0 10px; border: 0; border-radius: 4px; background: var(--accent); color: #fff; font-weight: 600; }
.sheet { position: fixed; inset: 0; z-index: 30; background: rgb(0 0 0 / 0.3); display: grid; place-items: center; }
.sheet-card { width: 420px; max-width: calc(100% - 32px); background: var(--panel); border-radius: 10px; padding: 16px 20px; box-shadow: 0 16px 48px rgb(0 0 0 / 0.25); }
.sheet-card h2 { margin: 0 0 10px; font-size: 13px; }
.sheet-card dl { display: grid; grid-template-columns: auto 1fr; gap: 6px 16px; margin: 0 0 14px; font-size: 12px; }
.sheet-card dt { color: var(--ink-2); white-space: nowrap; }
.sheet-card dd { margin: 0; }
.toast { position: fixed; z-index: 40; left: 50%; bottom: 20px; transform: translateX(-50%); background: #1e1e1e; color: #fff; padding: 8px 12px; border-radius: 6px; font-size: 12px; box-shadow: 0 4px 16px rgb(0 0 0 / 0.25); max-width: 560px; }
@media (prefers-reduced-motion: reduce) { .frame.flash { animation: none; } }

// dfw Studio in-frame agent, injected into every design document served by the
// Studio. It reports hover/selection geometry, layers, design-token usage and
// text edits to the parent Studio via postMessage, and forwards wheel/keys so
// the canvas can pan and zoom over frames. The Studio draws all chrome
// (selection boxes, pins) itself, in screen space. Framework-agnostic.
(() => {
  if (window.__dfwOverlay) return;
  window.__dfwOverlay = true;
  // dfw review (running app, see lib/live.mjs): only share the comment-target helpers with live.js.
  const LIVE = Boolean(document.currentScript && document.currentScript.hasAttribute('data-dfw-live'));
  const params = new URLSearchParams(location.search);
  if (!LIVE && params.get('theme')) document.documentElement.dataset.theme = params.get('theme');
  if (!LIVE && params.get('state')) document.documentElement.dataset.state = params.get('state');
  if (window.parent === window && !LIVE) return; // opened directly: plain page

  const post = (type, data = {}) => parent.postMessage({ type, ...data }, '*');
  let mode = 'select';
  let hoverEl = null;
  let selected = null;
  let editing = null;
  let midPan = false;
  let tokenVars = [];
  let tokenCache = null;
  let layerEls = [];
  let layerNode = new Map();
  let pins = [];

  const LANDMARK_TAGS = new Set(['HEADER', 'NAV', 'MAIN', 'ASIDE', 'FOOTER', 'FORM', 'DIALOG']);
  const LANDMARK_ROLES = new Set(['banner', 'navigation', 'main', 'complementary', 'contentinfo', 'region', 'search', 'form', 'dialog', 'alertdialog', 'toolbar', 'tablist']);
  const isUi = (el) => el && el.closest && el.closest('[data-dfw-ui]');
  const isLayer = (el) =>
    el.hasAttribute('data-dfw-id') || el.hasAttribute('data-dfw-component') || LANDMARK_TAGS.has(el.tagName) || LANDMARK_ROLES.has(el.getAttribute('role')) || (el.tagName === 'SECTION' && (el.hasAttribute('aria-label') || el.hasAttribute('aria-labelledby')));

  const rectOf = (el) => {
    const r = el.getBoundingClientRect();
    return [r.left, r.top, r.width, r.height];
  };

  function pick(el, exact) {
    if (!el || el.nodeType !== 1 || el === document.documentElement || el === document.body || isUi(el)) return null;
    if (exact) return el;
    return el.closest('[data-dfw-id],[data-dfw-component]') || el;
  }

  function labelOf(el) {
    if (el.dataset.dfwComponent) return `${el.dataset.dfwComponent}${el.dataset.dfwVariant ? ` · ${el.dataset.dfwVariant}` : ''}`;
    return el.dataset.dfwId || el.tagName.toLowerCase();
  }

  /* ---------- comment target info (feedback contract) ---------- */

  function cssPath(el) {
    if (el.dataset && el.dataset.dfwId) return `[data-dfw-id="${el.dataset.dfwId}"]`;
    const parts = [];
    let n = el;
    while (n && n.nodeType === 1 && n !== document.body) {
      if (n.id) {
        parts.unshift(`#${CSS.escape(n.id)}`);
        break;
      }
      const anc = n.parentElement && n.parentElement.closest('[data-dfw-id]');
      let sel = n.tagName.toLowerCase();
      const sibs = n.parentElement ? [...n.parentElement.children].filter((c) => c.tagName === n.tagName) : [];
      if (sibs.length > 1) sel += `:nth-of-type(${sibs.indexOf(n) + 1})`;
      parts.unshift(sel);
      if (anc && n.parentElement === anc) {
        parts.unshift(`[data-dfw-id="${anc.dataset.dfwId}"]`);
        break;
      }
      n = n.parentElement;
    }
    return parts.join(' > ');
  }

  const IMPLICIT_ROLE = { BUTTON: 'button', A: 'link', INPUT: 'textbox', SELECT: 'combobox', TEXTAREA: 'textbox', NAV: 'navigation', HEADER: 'banner', FOOTER: 'contentinfo', MAIN: 'main', FORM: 'form', TABLE: 'table', IMG: 'img', H1: 'heading', H2: 'heading', H3: 'heading', H4: 'heading', DIALOG: 'dialog', UL: 'list', OL: 'list', LI: 'listitem', SECTION: 'region', ASIDE: 'complementary' };

  function a11y(el) {
    let role = el.getAttribute('role') || IMPLICIT_ROLE[el.tagName] || null;
    if (el.tagName === 'INPUT') {
      const t = (el.getAttribute('type') || 'text').toLowerCase();
      role = { checkbox: 'checkbox', radio: 'radio', search: 'searchbox', button: 'button', submit: 'button', range: 'slider' }[t] || role;
    }
    let name = el.getAttribute('aria-label') || el.getAttribute('alt') || el.getAttribute('title') || '';
    if (!name && el.getAttribute('aria-labelledby')) name = el.getAttribute('aria-labelledby').split(/\s+/).map((id) => document.getElementById(id)?.textContent || '').join(' ');
    if (!name && el.id) name = document.querySelector(`label[for="${CSS.escape(el.id)}"]`)?.textContent || '';
    if (!name && el.getAttribute('placeholder')) name = el.getAttribute('placeholder');
    if (!name) name = el.textContent || '';
    return { role, name: name.replace(/\s+/g, ' ').trim().slice(0, 120) };
  }

  function info(el) {
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    return {
      dfwId: el.dataset?.dfwId || el.closest('[data-dfw-id]')?.dataset.dfwId || null,
      exact: !el.dataset?.dfwId,
      selector: cssPath(el),
      tag: el.tagName.toLowerCase(),
      component: el.dataset.dfwComponent || null,
      bbox: [Math.round(r.left + scrollX), Math.round(r.top + scrollY), Math.round(r.width), Math.round(r.height)],
      viewportBbox: [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)],
      a11y: a11y(el),
      text: (el.innerText || el.value || '').replace(/\s+/g, ' ').trim().slice(0, 160),
      styles: { color: cs.color, background: cs.backgroundColor, font: `${cs.fontWeight} ${cs.fontSize}/${cs.lineHeight} ${cs.fontFamily.split(',')[0]}`, padding: cs.padding, radius: cs.borderRadius },
      scroll: [Math.round(scrollX), Math.round(scrollY)],
    };
  }

  if (LIVE) {
    window.__dfwTargetInfo = info;
    return;
  }

  /* ---------- design tokens: reverse-map computed values to token names ---------- */

  const BASE = { color: 'rgb(1, 2, 3)', paddingLeft: '0px', fontWeight: '100', boxShadow: 'none', fontSize: '3.3px' };

  function buildTokenCache() {
    const box = document.createElement('div');
    box.setAttribute('data-dfw-ui', '');
    box.style.cssText = `position:absolute;left:-99999px;top:0;visibility:hidden;pointer-events:none;color:${BASE.color};font-size:${BASE.fontSize};font-weight:${BASE.fontWeight};`;
    const probes = tokenVars.map((t) => {
      const d = document.createElement('div');
      const v = `var(${t.var})`;
      d.style.cssText = `color:${v};padding-left:${v};font-weight:${v};box-shadow:${v};font-size:${v};`;
      box.append(d);
      return d;
    });
    (document.body || document.documentElement).append(box);
    const maps = { color: new Map(), length: new Map(), fontWeight: new Map(), shadow: new Map(), fontSize: new Map() };
    const add = (m, k, name) => (m.get(k) || m.set(k, []).get(k)).push(name);
    probes.forEach((d, i) => {
      const cs = getComputedStyle(d);
      const name = tokenVars[i].name;
      if (cs.color !== BASE.color) add(maps.color, cs.color, name);
      if (cs.paddingLeft !== BASE.paddingLeft) add(maps.length, cs.paddingLeft, name);
      if (cs.fontWeight !== BASE.fontWeight) add(maps.fontWeight, cs.fontWeight, name);
      if (cs.boxShadow !== BASE.boxShadow) add(maps.shadow, cs.boxShadow, name);
      if (cs.fontSize !== BASE.fontSize) add(maps.fontSize, cs.fontSize, name);
    });
    box.remove();
    return { key: `${document.documentElement.dataset.theme || ''}`, maps };
  }

  function lineHeightMap(fontSize) {
    const m = new Map();
    const box = document.createElement('div');
    box.setAttribute('data-dfw-ui', '');
    box.style.cssText = `position:absolute;left:-99999px;top:0;visibility:hidden;font-size:${fontSize};line-height:1.111;`;
    const base = document.createElement('div');
    box.append(base);
    const cand = tokenVars.filter((t) => /lead|line/i.test(t.name));
    const probes = cand.map((t) => {
      const d = document.createElement('div');
      d.style.lineHeight = `var(${t.var})`;
      box.append(d);
      return d;
    });
    (document.body || document.documentElement).append(box);
    const b = getComputedStyle(base).lineHeight;
    probes.forEach((d, i) => {
      const v = getComputedStyle(d).lineHeight;
      if (v !== b) (m.get(v) || m.set(v, []).get(v)).push(cand[i].name);
    });
    box.remove();
    return m;
  }

  const semanticFirst = (names) => [...names].sort((a, b) => /\.\d/.test(a) - /\.\d/.test(b) || a.length - b.length);
  const FAMILY = {
    padding: /^space\b|spacing/i,
    gap: /^space\b|spacing/i,
    margin: /^space\b|spacing/i,
    'border-radius': /radius|rounded/i,
    'font-size': /font|text|size/i,
    'font-weight': /weight|font/i,
    'line-height': /lead|line/i,
    'box-shadow': /shadow|elevation/i,
  };

  function match(group, value, map) {
    const names = map.get(value) || [];
    const fam = FAMILY[group];
    const ok = fam ? names.filter((n) => fam.test(n)) : names;
    return semanticFirst(ok);
  }

  function inspect(el) {
    if (!tokenCache || tokenCache.key !== `${document.documentElement.dataset.theme || ''}`) tokenCache = buildTokenCache();
    const M = tokenCache.maps;
    const cs = getComputedStyle(el);
    const rows = [];
    const row = (group, prop, value, map) => rows.push({ group, prop, value, tokens: match(group, value, map) });
    const transparent = (c) => c === 'rgba(0, 0, 0, 0)' || c === 'transparent';
    row('color', 'color', cs.color, M.color);
    if (!transparent(cs.backgroundColor)) row('background-color', 'background-color', cs.backgroundColor, M.color);
    if (parseFloat(cs.borderTopWidth) > 0 && cs.borderTopStyle !== 'none' && !transparent(cs.borderTopColor)) row('border-color', 'border-color', cs.borderTopColor, M.color);
    row('font-size', 'font-size', cs.fontSize, M.fontSize);
    row('font-weight', 'font-weight', cs.fontWeight, M.fontWeight);
    if (cs.lineHeight !== 'normal') row('line-height', 'line-height', cs.lineHeight, lineHeightMap(cs.fontSize));
    const sides = (group, names) => {
      const v = names.map((n) => cs.getPropertyValue(n));
      if (v.every((x) => x === '0px' || x === 'auto')) return;
      if (v.every((x) => x === v[0])) return row(group, group, v[0], M.length);
      if (v[0] === v[2] && v[1] === v[3] && group !== 'border-radius') {
        if (v[0] !== '0px') row(group, `${group}-block`, v[0], M.length);
        if (v[1] !== '0px') row(group, `${group}-inline`, v[1], M.length);
        return;
      }
      names.forEach((n, i) => v[i] !== '0px' && v[i] !== 'auto' && row(group, n, v[i], M.length));
    };
    sides('padding', ['padding-top', 'padding-right', 'padding-bottom', 'padding-left']);
    if (/flex|grid/.test(cs.display)) {
      const rg = cs.rowGap;
      const cg = cs.columnGap;
      if (rg === cg) {
        if (rg !== 'normal' && rg !== '0px') row('gap', 'gap', rg, M.length);
      } else {
        if (rg !== 'normal' && rg !== '0px') row('gap', 'row-gap', rg, M.length);
        if (cg !== 'normal' && cg !== '0px') row('gap', 'column-gap', cg, M.length);
      }
    }
    sides('margin', ['margin-top', 'margin-right', 'margin-bottom', 'margin-left']);
    sides('border-radius', ['border-top-left-radius', 'border-top-right-radius', 'border-bottom-right-radius', 'border-bottom-left-radius']);
    if (cs.boxShadow !== 'none') row('box-shadow', 'box-shadow', cs.boxShadow, M.shadow);
    return rows;
  }

  /* ---------- layers ---------- */

  function buildLayers() {
    layerEls = [];
    layerNode = new Map();
    const walk = (el, out, parentNode) => {
      for (const c of el.children) {
        if (c.hasAttribute('data-dfw-ui') || /^(SCRIPT|STYLE|TEMPLATE|LINK|META|NOSCRIPT)$/.test(c.tagName)) continue;
        if (layerEls.length > 3000) return;
        if (isLayer(c)) {
          const node = {
            i: layerEls.length,
            id: c.dataset.dfwId || null,
            comp: c.dataset.dfwComponent || null,
            variant: c.dataset.dfwVariant || null,
            size: c.dataset.dfwSize || null,
            tag: c.tagName.toLowerCase(),
            name: c.getAttribute('aria-label') || null,
            hidden: c.getClientRects().length === 0,
            children: [],
          };
          layerEls.push(c);
          layerNode.set(c, { node, parent: parentNode });
          out.push(node);
          walk(c, node.children, c);
        } else walk(c, out, parentNode);
      }
    };
    const tree = [];
    if (document.body) walk(document.body, tree, null);
    return tree;
  }

  function layerAncestor(el) {
    for (let n = el.parentElement; n && n !== document.body; n = n.parentElement) if (layerNode.has(n)) return n;
    return null;
  }

  /* ---------- text editing ---------- */

  const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();
  function editTarget(el) {
    if (!el || el.children.length) return { error: 'Only text-only elements can be edited in place.' };
    if (/^(INPUT|TEXTAREA|SELECT|IMG|SVG|svg)$/.test(el.tagName) || !norm(el.textContent)) return { error: 'This element has no text to edit.' };
    if (el.dataset.dfwId) return { el, id: el.dataset.dfwId };
    const host = el.closest('[data-dfw-id]');
    if (host && host.dataset.dfwComponent && norm(host.textContent) === norm(el.textContent)) return { el, id: host.dataset.dfwId };
    return { error: 'Give this element a data-dfw-id to edit it in place, or leave a comment.' };
  }

  function startEdit(el) {
    const t = editTarget(el);
    if (t.error) return post('dfw:toast', { message: t.error });
    editing = { el: t.el, id: t.id, orig: t.el.textContent };
    t.el.setAttribute('contenteditable', 'plaintext-only');
    t.el.focus();
    const range = document.createRange();
    range.selectNodeContents(t.el);
    const sel = getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
    t.el.addEventListener('blur', onEditBlur);
    placeHandles();
    post('dfw:editing', { on: true, id: t.id });
  }

  function onEditBlur() {
    endEdit(true);
  }

  function endEdit(save) {
    if (!editing) return;
    const { el, id, orig } = editing;
    editing = null;
    el.removeEventListener('blur', onEditBlur);
    el.removeAttribute('contenteditable');
    const text = el.textContent;
    if (!save) el.textContent = orig;
    getSelection()?.removeAllRanges();
    post('dfw:editing', { on: false, id });
    if (save && norm(text) !== norm(orig)) post('dfw:edit-text', { id, text: norm(text) });
    reportSelection();
  }

  /* ---------- selection & reporting ---------- */

  function selPayload(el, withInspect) {
    const t = editTarget(el);
    return {
      target: info(el),
      rect: rectOf(el),
      label: labelOf(el),
      layer: layerNode.get(el)?.node.i ?? null,
      own: { id: el.dataset.dfwId || null, comp: el.dataset.dfwComponent || null, variant: el.dataset.dfwVariant || null, size: el.dataset.dfwSize || null },
      textEditable: !t.error,
      inspect: withInspect ? inspect(el) : null,
    };
  }

  function select(el, { inspectIt = true, scroll = false } = {}) {
    selected = el;
    placeHandles();
    if (!el) return post('dfw:select', { target: null });
    if (scroll) el.scrollIntoView({ block: 'nearest' });
    post('dfw:select', { comment: mode === 'comment', ...selPayload(el, inspectIt && mode !== 'comment') });
  }

  function reportSelection() {
    if (selected && selected.isConnected) post('dfw:sel-rect', { rect: rectOf(selected) });
    placeHandles();
  }

  function reportPins() {
    const out = [];
    for (const p of pins) {
      let el = null;
      try {
        el = (p.selector && document.querySelector(p.selector)) || (p.dfwId && document.querySelector(`[data-dfw-id="${CSS.escape(p.dfwId)}"]`)) || null;
      } catch {}
      if (el && el.getClientRects().length) out.push({ id: p.id, rect: rectOf(el) });
    }
    post('dfw:pin-rects', { pins: out });
  }

  function reportSize() {
    const d = document.documentElement;
    post('dfw:size', { h: Math.max(d.scrollHeight, document.body ? document.body.scrollHeight : 0), title: document.title });
  }

  /* ---------- layout: drag to reorder, resize with snapping (edit mode) ----------
   * Constrained on purpose: no free positioning. Dragging reorders an element among the
   * data-dfw-id children of a flex/grid container; resizing snaps to the grid (column span)
   * or to tokens / fixed percentages. The Studio writes the change to the screen source. */

  let layoutCfg = { enabled: false, scope: '' };
  let drag = null; // { el, x, y, active, drop, prevOpacity, prevPointer }
  let resize = null; // { el, axis, rect, x, y, moved, pick, prop, prev }
  let suppressClick = false;
  let lengthCache = null;
  const FLOW = /^(inline-)?(flex|grid)$/;
  const isFlow = (el) => !!el && el.nodeType === 1 && FLOW.test(getComputedStyle(el).display);
  const isGrid = (el) => /grid$/.test(getComputedStyle(el).display);
  const idKids = (c) => [...c.children].filter((x) => x.dataset && x.dataset.dfwId && !x.hasAttribute('data-dfw-ui') && x.getClientRects().length);
  const canLayout = (el) => layoutCfg.enabled && mode === 'select' && !editing && el && el.isConnected && !!el.dataset.dfwId && el !== document.body;
  const canMove = (el) => canLayout(el) && isFlow(el.parentElement);
  const PERCENTS = [25, 33.333, 50, 66.667, 75, 100];

  const ui = document.createElement('div');
  ui.setAttribute('data-dfw-ui', '');
  ui.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:2147483646;';
  const mk = (css) => {
    const d = document.createElement('div');
    d.setAttribute('data-dfw-ui', '');
    d.style.cssText = `position:fixed;display:none;box-sizing:border-box;${css}`;
    ui.append(d);
    return d;
  };
  const HANDLE = 'width:10px;height:10px;background:#fff;border:2px solid #0d99ff;border-radius:2px;pointer-events:auto;';
  const hX = mk(`${HANDLE}cursor:ew-resize;`);
  const hY = mk(`${HANDLE}cursor:ns-resize;`);
  hX.dataset.dfwHandle = 'x';
  hY.dataset.dfwHandle = 'y';
  hX.title = 'Drag to resize the width (snaps to grid columns, size tokens or percentages). Alt+Shift+Left/Right. Double-click: back to auto';
  hY.title = 'Drag to set a min-height (snaps to spacing/size tokens). Alt+Shift+Up/Down. Double-click: back to auto';
  const line = mk('background:#0d99ff;border-radius:2px;');
  const zone = mk('border:2px dashed #0d99ff;background:rgba(13,153,255,.12);border-radius:4px;'); // drop-into-container highlight
  const badge = mk('padding:2px 6px;border-radius:4px;background:#0d99ff;color:#fff;font:600 11px/16px system-ui,sans-serif;white-space:nowrap;');
  const mountUi = () => !ui.isConnected && (document.body || document.documentElement).append(ui);

  function placeHandles() {
    const show = !drag?.active && !resize?.moved && selected && canLayout(selected) && selected.getClientRects().length;
    hX.style.display = hY.style.display = show ? 'block' : 'none';
    if (!show) return;
    mountUi();
    const r = selected.getBoundingClientRect();
    hX.style.left = `${r.right - 5}px`;
    hX.style.top = `${r.top + r.height / 2 - 5}px`;
    hY.style.left = `${r.left + r.width / 2 - 5}px`;
    hY.style.top = `${r.bottom - 5}px`;
  }

  function showBadge(text, x, y) {
    mountUi();
    badge.textContent = text;
    badge.style.display = 'block';
    badge.style.left = `${Math.min(x + 12, innerWidth - badge.offsetWidth - 4)}px`;
    badge.style.top = `${Math.max(4, y - 28)}px`;
  }
  const hideFeedback = () => {
    line.style.display = 'none';
    zone.style.display = 'none';
    badge.style.display = 'none';
  };
  const scoped = (t) => (layoutCfg.scope ? `${t} · ${layoutCfg.scope}` : t);

  /** px value of every space.* / size.* dimension token (resolved in this document). */
  function tokenLengths() {
    const key = document.documentElement.dataset.theme || '';
    if (lengthCache && lengthCache.key === key && lengthCache.n === tokenVars.length) return lengthCache.list;
    const box = document.createElement('div');
    box.setAttribute('data-dfw-ui', '');
    box.style.cssText = 'position:absolute;left:-99999px;top:0;visibility:hidden;';
    const cand = tokenVars.filter((t) => /^(space|size)\./.test(t.name) && t.type !== 'typography');
    const probes = cand.map((t) => {
      const d = document.createElement('div');
      d.style.cssText = `width:var(${t.var});height:0;`;
      box.append(d);
      return d;
    });
    (document.body || document.documentElement).append(box);
    const list = probes.map((d, i) => ({ name: cand[i].name, var: cand[i].var, px: d.getBoundingClientRect().width })).filter((t) => t.px > 0);
    box.remove();
    list.sort((a, b) => a.px - b.px || /\.\d/.test(a.name) - /\.\d/.test(b.name));
    lengthCache = { key, n: tokenVars.length, list };
    return list;
  }

  /** Snap options for a resize: [{ value (sent to the server), css (preview), label, px }] sorted by px. */
  function snapOptions(el, axis) {
    const p = el.parentElement;
    if (axis === 'x' && isGrid(p)) {
      const cs = getComputedStyle(p);
      const tracks = cs.gridTemplateColumns.split(/\s+/).filter((t) => /px$/.test(t)).map(parseFloat);
      const gap = parseFloat(cs.columnGap) || 0;
      const n = Math.max(1, tracks.length);
      const track = tracks.length ? tracks.reduce((a, b) => a + b, 0) / tracks.length : p.clientWidth;
      return { prop: 'grid-column', list: Array.from({ length: n }, (_, i) => ({ value: `span ${i + 1}`, css: `span ${i + 1}`, label: `span ${i + 1} / ${n}`, px: (i + 1) * track + i * gap })) };
    }
    const toks = tokenLengths();
    if (axis === 'x') {
      const pcs = getComputedStyle(p);
      const inner = p.clientWidth - parseFloat(pcs.paddingLeft) - parseFloat(pcs.paddingRight);
      const pct = PERCENTS.map((v) => ({ value: `${v}%`, css: `${v}%`, label: `${Math.round(v)}%`, px: (inner * v) / 100 }));
      const sizes = toks.filter((t) => t.name.startsWith('size.') && t.px <= inner).map((t) => ({ value: t.name, css: `var(${t.var})`, label: `${t.name} · ${Math.round(t.px)}px`, px: t.px }));
      return { prop: 'width', list: [...pct, ...sizes].sort((a, b) => a.px - b.px) };
    }
    return { prop: 'min-height', list: toks.map((t) => ({ value: t.name, css: `var(${t.var})`, label: `${t.name} · ${Math.round(t.px)}px`, px: t.px })) };
  }

  const nearest = (list, px) => list.reduce((best, o) => (Math.abs(o.px - px) < Math.abs(best.px - px) ? o : best), list[0]);
  const styleProp = { 'grid-column': 'gridColumn', width: 'width', 'min-height': 'minHeight' };

  function startResize(axis, e) {
    const el = selected;
    const opts = snapOptions(el, axis);
    if (!opts.list.length) return post('dfw:toast', { message: 'No size tokens to snap to.' });
    resize = { el, axis, rect: el.getBoundingClientRect(), x: e.clientX, y: e.clientY, moved: false, ...opts, pick: null, prev: el.style[styleProp[opts.prop]] };
    placeHandles();
  }

  function moveResize(e) {
    const r = resize;
    // A click (or the double-click that resets) on a handle is not a resize.
    if (!r.moved && Math.hypot(e.clientX - r.x, e.clientY - r.y) < 3) return;
    if (!r.moved) {
      r.moved = true;
      placeHandles();
    }
    const px = r.axis === 'x' ? e.clientX - r.rect.left : e.clientY - r.rect.top;
    const o = nearest(r.list, px);
    if (o !== r.pick) {
      r.pick = o;
      r.el.style[styleProp[r.prop]] = o.css;
      reportSelection();
    }
    showBadge(scoped(r.prop === 'grid-column' ? o.label : `${r.prop} ${o.label}`), e.clientX, e.clientY);
  }

  function endResize(commit) {
    const r = resize;
    resize = null;
    hideFeedback();
    if (commit && r.moved && r.pick) post('dfw:layout-op', { op: 'layout', id: r.el.dataset.dfwId, prop: r.prop, value: r.pick.value, label: r.pick.label });
    else r.el.style[styleProp[r.prop]] = r.prev;
    placeHandles();
    reportSelection();
  }

  /** An empty flex/grid container with a data-dfw-id: nothing in it but whitespace (and dfw UI). */
  const isEmptyBox = (n) => n.dataset && n.dataset.dfwId && isFlow(n) && ![...n.children].some((k) => !k.hasAttribute('data-dfw-ui')) && !n.textContent.trim();

  /**
   * Where a dragged element would land: { ref, position, vertical } next to a data-dfw-id child of a flex/grid
   * container, or { ref: container, position: 'inside' } over an empty flex/grid container that has a data-dfw-id.
   */
  function dropAt(x, y) {
    const d = drag.el;
    let n = document.elementFromPoint(x, y);
    let c = null;
    const home = d.parentElement;
    for (let e = n; e && e !== home && e !== document.documentElement; e = e.parentElement) {
      if (isUi(e) || d.contains(e)) break;
      if (isEmptyBox(e)) return { ref: e, position: 'inside', r: e.getBoundingClientRect() };
      if (isFlow(e) && idKids(e).length) break;
    }
    const hr = home.getBoundingClientRect();
    if (x >= hr.left && x <= hr.right && y >= hr.top && y <= hr.bottom) c = home;
    for (; !c && n && n !== document.documentElement; n = n.parentElement) {
      if (isUi(n) || d.contains(n)) return null;
      if (isFlow(n) && idKids(n).some((k) => k !== d)) c = n;
    }
    if (!c) return null;
    const kids = idKids(c).filter((k) => k !== d);
    if (!kids.length) return null;
    const dist = (r) => Math.hypot(Math.max(r.left - x, 0, x - r.right), Math.max(r.top - y, 0, y - r.bottom));
    let best = null;
    for (const k of kids) {
      const r = k.getBoundingClientRect();
      const dd = dist(r);
      if (!best || dd < best.dd) best = { k, r, dd };
    }
    const { k, r } = best;
    let horizontal; // true: decide by x (items flow left-right)
    if (isGrid(c)) horizontal = y >= r.top && y <= r.bottom;
    else horizontal = getComputedStyle(c).flexDirection.startsWith('row');
    const before = horizontal ? x < r.left + r.width / 2 : y < r.top + r.height / 2;
    return { ref: k, position: before ? 'before' : 'after', vertical: horizontal, r };
  }

  function moveDrag(e) {
    if (!drag.active) {
      if (Math.hypot(e.clientX - drag.x, e.clientY - drag.y) < 5) return;
      drag.active = true;
      drag.prevOpacity = drag.el.style.opacity;
      drag.prevPointer = drag.el.style.pointerEvents;
      drag.el.style.opacity = '0.4';
      drag.el.style.pointerEvents = 'none';
      placeHandles();
      post('dfw:hover', { rect: null });
    }
    const t = (drag.drop = dropAt(e.clientX, e.clientY));
    mountUi();
    if (!t) {
      line.style.display = zone.style.display = 'none';
      return showBadge('Drop next to a sibling in a flex or grid container, or into an empty one', e.clientX, e.clientY);
    }
    const { r } = t;
    if (t.position === 'inside') {
      line.style.display = 'none';
      Object.assign(zone.style, { left: `${r.left}px`, top: `${r.top}px`, width: `${r.width}px`, height: `${Math.max(r.height, 8)}px`, display: 'block' });
      return showBadge(`Into ${t.ref.dataset.dfwId}`, e.clientX, e.clientY);
    }
    zone.style.display = 'none';
    const edge = t.position === 'before' ? (t.vertical ? r.left : r.top) : t.vertical ? r.right : r.bottom;
    Object.assign(line.style, t.vertical ? { left: `${edge - 2}px`, top: `${r.top}px`, width: '3px', height: `${r.height}px` } : { left: `${r.left}px`, top: `${edge - 2}px`, width: `${r.width}px`, height: '3px' });
    line.style.display = 'block';
    showBadge(`${t.position === 'before' ? 'Before' : 'After'} ${t.ref.dataset.dfwId}`, e.clientX, e.clientY);
  }

  function endDrag(commit) {
    const g = drag;
    drag = null;
    hideFeedback();
    if (!g?.active) return placeHandles();
    g.el.style.opacity = g.prevOpacity;
    g.el.style.pointerEvents = g.prevPointer;
    suppressClick = true; // the click that ends the drag must not re-select (reset on the next mousedown)
    const t = g.drop;
    if (commit && t && t.position === 'inside') {
      t.ref.append(g.el); // optimistic; the frame reloads from the source
      post('dfw:layout-op', { op: 'move', id: g.el.dataset.dfwId, ref: t.ref.dataset.dfwId, position: 'inside', label: `Moved into ${t.ref.dataset.dfwId}` });
    } else if (commit && t) {
      const next = t.position === 'before' ? t.ref : t.ref.nextSibling;
      if (next !== g.el && !(t.position === 'before' && g.el.nextElementSibling === t.ref) && !(t.position === 'after' && t.ref.nextElementSibling === g.el)) {
        t.ref.parentElement.insertBefore(g.el, next); // optimistic; the frame reloads from the source
        post('dfw:layout-op', { op: 'move', id: g.el.dataset.dfwId, ref: t.ref.dataset.dfwId, position: t.position, label: `Moved ${t.position} ${t.ref.dataset.dfwId}` });
      }
    }
    placeHandles();
    reportSelection();
  }

  /** Reset to auto: drop the element's layout rule (prop null: the whole rule) at this frame's breakpoint scope. */
  function resetLayout(el, prop = null) {
    for (const p of prop ? [prop] : Object.keys(styleProp)) el.style[styleProp[p]] = '';
    reportSelection();
    placeHandles();
    post('dfw:layout-op', { op: 'layout', id: el.dataset.dfwId, prop, value: null, label: prop ? `${prop} reset to auto` : 'Size reset to auto' });
  }

  /** Style rules of a sheet (recursing into @media that matches now, @layer, @supports) for which pick(rule) is truthy. */
  function rulesOf(rules, pick, out = []) {
    for (const r of rules) {
      if (r.cssRules && !r.selectorText) {
        if (!r.media || matchMedia(r.media.mediaText).matches) rulesOf(r.cssRules, pick, out);
      } else if (r.selectorText && pick(r)) out.push(r);
    }
    return out;
  }

  /**
   * After a resize was written and the frame reloaded: check the element's computed value really changed.
   * If a screen rule still wins (an id selector, inline style or !important), name it instead of failing silently.
   */
  function verifyLayout(d) {
    const el = document.querySelector(`[data-dfw-id="${CSS.escape(d.id)}"]`);
    const sheet = document.querySelector('style[data-dfw-layout]')?.sheet;
    if (!el || !sheet || !styleProp[d.prop]) return;
    const own = rulesOf(sheet.cssRules, (r) => r.style.getPropertyValue(d.prop) && el.matches(r.selectorText));
    if (!own.length) return; // not at this width (or already reset)
    const read = () => (d.prop === 'grid-column' ? ['gridColumnStart', 'gridColumnEnd'] : [styleProp[d.prop]]).map((k) => getComputedStyle(el)[k]).join(' / ');
    const prev = el.style.getPropertyValue(d.prop);
    const prevPrio = el.style.getPropertyPriority(d.prop);
    const now = read();
    el.style.setProperty(d.prop, own.at(-1).style.getPropertyValue(d.prop), 'important');
    const ideal = read();
    el.style.setProperty(d.prop, prev, prevPrio);
    if (now === ideal) return;
    const by = conflictFor(el, d.prop, sheet);
    post('dfw:layout-conflict', { id: d.id, prop: d.prop, selector: by });
    post('dfw:toast', {
      message: `Saved, but ${d.id} did not change: ${by ? `"${by}"` : 'another rule'} still sets ${d.prop}${by === 'style attribute' ? '' : ' with higher priority'}. Remove ${d.prop} there (or ask Claude), then resize again.`,
    });
  }

  const LONGHANDS = { 'grid-column': ['grid-column', 'grid-column-start', 'grid-column-end', 'grid-area'], width: ['width'], 'min-height': ['min-height'] };
  /** Rough selector specificity [ids, classes/attributes/pseudo-classes, types], only to rank conflicting rules. */
  function specificity(sel) {
    const s = sel.replace(/:where\([^)]*\)/g, '').replace(/:(?:not|is|has)\(/g, '(').replace(/"[^"]*"|'[^']*'/g, '');
    return [(s.match(/#[\w-]/g) || []).length, (s.match(/\.[\w-]|\[|:(?!:)[\w-]/g) || []).length, (s.replace(/[#.:][\w-]+|\[[^\]]*\]/g, ' ').match(/(^|[\s>+~(,])[a-z][\w-]*/gi) || []).length];
  }
  /** Selector of the rule that beats the dfw layout rule for prop on el (inline style, then !important, then specificity). */
  function conflictFor(el, prop, dfwSheet) {
    const names = LONGHANDS[prop];
    if (names.some((n) => el.style.getPropertyValue(n))) return 'style attribute';
    const hits = [];
    const matches = (x) => {
      try {
        return el.matches(x);
      } catch {
        return false;
      }
    };
    for (const sh of document.styleSheets) {
      if (sh === dfwSheet) continue;
      let rules = [];
      try {
        rules = rulesOf(sh.cssRules, (r) => names.some((n) => r.style.getPropertyValue(n)));
      } catch {} // cross-origin sheet
      for (const r of rules) {
        const sel = r.selectorText.split(',').map((x) => x.trim()).find(matches);
        const n = names.find((x) => r.style.getPropertyValue(x));
        if (sel) hits.push({ sel, imp: r.style.getPropertyPriority(n) === 'important', sp: specificity(sel) });
      }
    }
    hits.sort((a, b) => b.imp - a.imp || b.sp[0] - a.sp[0] || b.sp[1] - a.sp[1] || b.sp[2] - a.sp[2]);
    return hits[0]?.sel || null;
  }

  /** Alt+Arrow: move among siblings; Alt+Shift+Arrow: step the span / width (Left/Right) or min-height (Up/Down); Alt+Shift+0: reset. */
  function layoutKey(key, shift) {
    const el = selected;
    if (!canLayout(el)) return post('dfw:toast', { message: 'Select an element with a data-dfw-id to move or resize it.' });
    if (key === 'reset') return resetLayout(el);
    const back = key === 'ArrowLeft' || key === 'ArrowUp';
    if (!shift) {
      if (!canMove(el)) return post('dfw:toast', { message: 'Only children of a flex or grid container can be reordered.' });
      const sibs = idKids(el.parentElement);
      const i = sibs.indexOf(el);
      const ref = sibs[back ? i - 1 : i + 1];
      if (!ref) return post('dfw:toast', { message: back ? 'Already the first item.' : 'Already the last item.' });
      const position = back ? 'before' : 'after';
      ref.parentElement.insertBefore(el, back ? ref : ref.nextSibling);
      reportSelection();
      return post('dfw:layout-op', { op: 'move', id: el.dataset.dfwId, ref: ref.dataset.dfwId, position, label: `Moved ${position} ${ref.dataset.dfwId}` });
    }
    const axis = key === 'ArrowLeft' || key === 'ArrowRight' ? 'x' : 'y';
    const { prop, list } = snapOptions(el, axis);
    if (!list.length) return post('dfw:toast', { message: 'No size tokens to snap to.' });
    let cur;
    if (prop === 'grid-column') {
      const m = /span\s+(\d+)/.exec(getComputedStyle(el).gridColumnEnd) || /span\s+(\d+)/.exec(getComputedStyle(el).gridColumnStart);
      cur = list.findIndex((o) => o.value === `span ${m ? m[1] : 1}`);
    } else {
      const now = axis === 'x' ? el.getBoundingClientRect().width : parseFloat(getComputedStyle(el).minHeight) || 0;
      cur = list.indexOf(nearest(list, now));
      if (axis === 'y' && !now) cur = -1;
    }
    const o = list[Math.max(0, Math.min(list.length - 1, cur + (back ? -1 : 1)))];
    if (cur >= 0 && o === list[cur]) return post('dfw:toast', { message: `Already ${o.label}.` });
    el.style[styleProp[prop]] = o.css;
    reportSelection();
    post('dfw:layout-op', { op: 'layout', id: el.dataset.dfwId, prop, value: o.value, label: o.label });
  }

  /* ---------- events ---------- */

  const capture = { capture: true };
  const interactive = () => mode === 'select' || mode === 'comment';
  const inEdit = (t) => editing && editing.el.contains(t);

  let raf = 0;
  document.addEventListener(
    'mousemove',
    (e) => {
      if (midPan) return post('dfw:pan', { phase: 'move', sx: e.screenX, sy: e.screenY });
      if (resize || drag) {
        if (!(e.buttons & 1)) return resize ? endResize(false) : endDrag(false); // released outside the frame
        return resize ? moveResize(e) : moveDrag(e);
      }
      if (!interactive() || editing) return;
      const t = pick(e.target, e.metaKey || e.ctrlKey || e.altKey);
      if (t === hoverEl) return;
      hoverEl = t;
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => post('dfw:hover', t ? { rect: rectOf(t), label: labelOf(t), comp: !!t.dataset.dfwComponent } : { rect: null }));
    },
    capture,
  );
  document.addEventListener('mouseleave', () => {
    hoverEl = null;
    post('dfw:hover', { rect: null });
  });
  document.addEventListener(
    'mousedown',
    (e) => {
      if (e.button === 1 && mode !== 'present') {
        e.preventDefault();
        midPan = true;
        return post('dfw:pan', { phase: 'start', sx: e.screenX, sy: e.screenY });
      }
      suppressClick = false;
      if (inEdit(e.target)) return;
      if (editing) endEdit(true);
      if (interactive() && !isUi(e.target)) {
        e.preventDefault();
        e.stopPropagation();
      }
      post('dfw:focus');
      if (e.button !== 0 || mode !== 'select') return;
      if (e.target.dataset && e.target.dataset.dfwHandle && canLayout(selected)) {
        e.preventDefault();
        e.stopPropagation();
